// palette.js -- command palette + snippet inserter for the workspace editor.
//
// Reads window.LILYPOND_SYNTAX (generated by scripts/build-syntax.js; do not
// hand-edit the data). Plain script, no bundler, matching public/*.js.
//
// What it does, and deliberately does NOT do:
//   - filter box + scope filter + collapsible category nav
//   - click to insert at cursor (templates replace the whole editor)
//   - shell commands copy to the clipboard, never into the .ly source
//   - verified / fails-as-documented / unverified badges from the payload
//   - a brace-depth placement guard for the unambiguous cases only
// It is NOT autocomplete, NOT syntax highlighting, NOT a score builder.

(function () {
  "use strict";

  var data = window.LILYPOND_SYNTAX;
  var catsEl = document.getElementById("palCats");
  if (!data || !catsEl) return;

  var editor = document.getElementById("editor");
  var filterEl = document.getElementById("palFilter");
  var scopeEl = document.getElementById("palScope");
  var msgEl = document.getElementById("palMsg");
  var countsEl = document.getElementById("palCounts");

  function triggerCompile() {
    // app.js owns compilation; reuse it so insertions behave exactly like typing.
    if (typeof scheduleCompile === "function") scheduleCompile(true);
    else if (editor) editor.dispatchEvent(new Event("input", { bubbles: true }));
  }

  function say(text) {
    if (!msgEl) return;
    msgEl.hidden = !text;
    msgEl.textContent = text || "";
  }

  // ---- Placement guard -------------------------------------------------
  // LilyPond placement errors are compile errors, and finding out by
  // compiling is the slow path. This counts brace depth at the cursor,
  // skipping % line comments, %{ %} block comments and "..." strings, and
  // blocks only the placements that are CERTAINLY wrong:
  //   - scope "top"/"paper" inside any block (top-level blocks in music
  //     are always syntax errors; \paper belongs at file scope)
  //   - music-like scopes at brace depth 0 (bare music with no \score
  //     around it is always an error)
  // Everything else is allowed with the scope tag shown, because a false
  // block is worse than no block: markup, for example, is legal both in
  // \markup blocks and as post-events in music.
  var MUSIC_SCOPES = { music: 1, score: 1, chordmode: 1, lyricmode: 1, drum: 1, context: 1 };

  function braceDepth(src, pos) {
    var depth = 0, i = 0, inStr = false, inBlock = false;
    while (i < pos) {
      var c = src[i], n = src[i + 1];
      if (inStr) {
        if (c === "\\") i += 2;
        else { if (c === '"') inStr = false; i++; }
        continue;
      }
      if (!inBlock && c === "%" && n === "{") { inBlock = true; i += 2; continue; }
      if (inBlock) {
        if (c === "%" && n === "}") inBlock = false, i += 2;
        else i++;
        continue;
      }
      if (c === "%") { while (i < pos && src[i] !== "\n") i++; continue; }
      if (c === '"') { inStr = true; i++; continue; }
      if (c === "{") depth++;
      else if (c === "}") depth = Math.max(0, depth - 1);
      i++;
    }
    return depth;
  }

  function placementError(entry) {
    if (!editor) return null;
    var at = editor.selectionStart == null ? editor.value.length : editor.selectionStart;
    var depth = braceDepth(editor.value, at);
    var rule = placementRule(entry.scope, depth);
    if (rule === "top") {
      return "\u201C" + entry.name + "\u201D lives at file top level, but the cursor is inside a block. Move the cursor above or below your \\score first.";
    }
    if (rule === "music") {
      return "\u201C" + entry.name + "\u201D is music and needs a score around it. Put the cursor inside a \\score { } block first.";
    }
    return null;
  }

  // ---- Actions ---------------------------------------------------------
  function doInsert(entry) {
    if (!editor) return;
    var blocked = placementError(entry);
    if (blocked) { say(blocked); editor.focus(); return; }
    say("");
    editor.focus();
    var start = editor.selectionStart == null ? editor.value.length : editor.selectionStart;
    var end = editor.selectionEnd == null ? start : editor.selectionEnd;
    // setRangeText preserves the undo stack, unlike value reassignment.
    editor.setRangeText(entry.insert, start, end, "end");
    triggerCompile();
  }

  function doTemplate(entry) {
    if (!editor) return;
    if (!window.confirm("Replace the whole editor with the \u201C" + entry.name + "\u201D template?")) return;
    say("");
    editor.focus();
    editor.value = entry.insert;
    editor.selectionStart = editor.selectionEnd = 0;
    triggerCompile();
  }

  function doCopy(entry, btn) {
    var text = entry.copy;
    var done = function () {
      var old = btn.textContent;
      btn.textContent = "copied \u2713";
      setTimeout(function () { btn.textContent = old; }, 1200);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done, function () { fallbackCopy(text); done(); });
    } else { fallbackCopy(text); done(); }
  }

  function fallbackCopy(text) {
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand("copy"); } catch (_) {}
    document.body.removeChild(ta);
  }

  // ---- Rendering -------------------------------------------------------
  function badge(entry) {
    var s = document.createElement("span");
    if (entry.verification === "expected-failure") {
      s.className = "pal-badge pal-xfail";
      s.textContent = "fails as documented";
      s.title = "Verified: this reproduces the documented failure on " + data.lilypond;
    } else if (entry.verified) {
      s.className = "pal-badge pal-ok";
      s.textContent = "\u2713 verified";
      s.title = "Compiles clean on " + data.lilypond;
    } else {
      s.className = "pal-badge pal-unver";
      s.textContent = "unverified";
      s.title = entry.why || "No compile probe covers this yet";
    }
    return s;
  }

  function scopeTag(scope) {
    var s = document.createElement("span");
    s.className = "pal-scope";
    s.textContent = scope;
    return s;
  }

  function infoToggle(entry) {
    var wrap = document.createElement("div");
    wrap.className = "pal-info";
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "pal-info-btn";
    btn.textContent = "i";
    btn.title = "About this entry";
    btn.setAttribute("aria-label", "About " + entry.name);
    btn.setAttribute("aria-expanded", "false");
    var body = document.createElement("div");
    body.className = "pal-info-body";
    body.hidden = true;
    var html = "";
    if (entry.desc) html += "<p>" + escapeHtml(entry.desc) + "</p>";
    if (entry.syntax) html += '<p class="mono">' + escapeHtml(entry.syntax) + "</p>";
    if (entry.note) html += "<p>" + escapeHtml(entry.note).replace(/\n/g, "<br>") + "</p>";
    (entry.gotchas || []).forEach(function (g) {
      html += '<p class="pal-gotcha">' + escapeHtml(g).replace(/\n/g, "<br>") + "</p>";
    });
    if (!entry.verified && entry.why) html += '<p class="pal-why">' + escapeHtml(entry.why) + "</p>";
    body.innerHTML = html || "<p>No notes.</p>";
    btn.onclick = function () {
      body.hidden = !body.hidden;
      btn.setAttribute("aria-expanded", String(!body.hidden));
    };
    wrap.appendChild(btn);
    wrap.appendChild(body);
    return wrap;
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function isActionable(entry) {
    return (entry.insert || entry.copy) &&
      entry.kind !== "note" && entry.kind !== "warning";
  }

  function renderEntry(entry) {
    var li = document.createElement("li");
    li.className = "pal-entry";
    li.dataset.search = (entry.name + " " + (entry.syntax || "") + " " +
      (entry.desc || "") + " " + entry.id).toLowerCase();
    li.dataset.scope = entry.scope;

    var row = document.createElement("div");
    row.className = "pal-row";

    if (isActionable(entry)) {
      if (entry.insert && entry.kind === "template") {
        var t = document.createElement("button");
        t.type = "button";
        t.className = "pal-act pal-template";
        t.textContent = entry.name;
        t.title = "Replace editor with this whole-score template";
        t.onclick = function () { doTemplate(entry); };
        row.appendChild(t);
      } else {
        if (entry.insert) {
          var b = document.createElement("button");
          b.type = "button";
          b.className = "pal-act";
          b.textContent = entry.name;
          b.title = "Insert at cursor";
          b.onclick = (function (e) { return function () { doInsert(e); }; })(entry);
          row.appendChild(b);
        }
        if (entry.copy) {
          var c = document.createElement("button");
          c.type = "button";
          c.className = "pal-act pal-copy";
          c.textContent = entry.insert ? "copy cmd" : entry.name;
          c.title = "Copy shell command to clipboard (not into the score)";
          c.onclick = (function (e, btn) { return function () { doCopy(e, btn); }; })(entry, c);
          row.appendChild(c);
        }
      }
    } else {
      var ref = document.createElement("span");
      ref.className = "pal-ref";
      ref.textContent = entry.name;
      row.appendChild(ref);
    }
    row.appendChild(scopeTag(entry.scope));
    row.appendChild(badge(entry));
    li.appendChild(row);
    li.appendChild(infoToggle(entry));
    return li;
  }

  function render() {
    catsEl.innerHTML = "";
    data.categories.forEach(function (cat) {
      var det = document.createElement("details");
      det.className = "pal-cat";
      det.dataset.cat = cat.id;
      var sum = document.createElement("summary");
      var verified = cat.entries.filter(function (e) { return e.verified; }).length;
      sum.textContent = cat.title + "  (" + verified + "/" + cat.entries.length + ")";
      sum.title = cat.blurb || "";
      det.appendChild(sum);
      if (cat.blurb) {
        var bl = document.createElement("p");
        bl.className = "pal-blurb";
        bl.textContent = cat.blurb;
        det.appendChild(bl);
      }
      var ul = document.createElement("ul");
      ul.className = "pal-list";
      cat.entries.forEach(function (e) { ul.appendChild(renderEntry(e)); });
      det.appendChild(ul);
      catsEl.appendChild(det);
    });
  }

  // ---- Filter ----------------------------------------------------------
  function applyFilter() {
    var q = (filterEl.value || "").trim().toLowerCase();
    var scope = scopeEl.value;
    var openAll = q.length > 0;
    catsEl.querySelectorAll("details.pal-cat").forEach(function (det) {
      var shown = 0;
      det.querySelectorAll("li.pal-entry").forEach(function (li) {
        var okQ = !q || li.dataset.search.indexOf(q) !== -1;
        var okS = scope === "" || li.dataset.scope === scope;
        var show = okQ && okS;
        li.hidden = !show;
        if (show) shown++;
      });
      det.hidden = shown === 0;
      if (openAll) det.open = shown > 0;
    });
    say("");
  }

  // Populate the scope dropdown from the data, so new scopes never need HTML edits.
  function fillScopes() {
    var seen = {};
    data.categories.forEach(function (c) {
      c.entries.forEach(function (e) { seen[e.scope] = 1; });
    });
    Object.keys(seen).sort().forEach(function (s) {
      var o = document.createElement("option");
      o.value = o.textContent = s;
      scopeEl.appendChild(o);
    });
  }

  // ---- Collapse --------------------------------------------------------
  var KEY = "lily-palette-open";
  var aside = document.getElementById("palette");
  function setOpen(open) {
    if (aside) aside.hidden = !open;
    var t = document.getElementById("palToggle");
    if (t) t.setAttribute("aria-expanded", String(open));
    try { localStorage.setItem(KEY, open ? "1" : "0"); } catch (_) {}
  }
  function initCollapse() {
    var open = true;
    try { open = localStorage.getItem(KEY) !== "0"; } catch (_) {}
    setOpen(open);
    var t = document.getElementById("palToggle");
    if (t) t.onclick = function () { setOpen(aside.hidden); };
    var c = document.getElementById("palClose");
    if (c) c.onclick = function () { setOpen(false); };
  }

  // Test hook: pure logic with no DOM side effects, exercised by a node
  // smoke test (no browser here). Read-only; not used by the UI itself.
  function placementRule(scope, depth) {
    if ((scope === "top" || scope === "paper") && depth > 0) return "top";
    if (MUSIC_SCOPES[scope] && depth === 0) return "music";
    return null;
  }
  window.__paletteTest = { braceDepth: braceDepth, placementRule: placementRule };

  // ---- Init ------------------------------------------------------------
  countsEl.textContent = data.counts.verified + " verified \u00B7 " +
    data.counts.unprobed + " unverified \u00B7 " + data.lilypond;
  countsEl.title = "Generated " + data.generated;
  fillScopes();
  render();
  filterEl.addEventListener("input", applyFilter);
  scopeEl.addEventListener("change", applyFilter);
  initCollapse();
})();
